import Link from "next/link"; import Image from "next/image"; import { notFound } from "next/navigation"; import { AppShell } from "@/components/AppShell"; import { PreviewGate } from "@/components/PreviewGate"; import { ModuleBreadcrumb, ModulePager } from "@/components/ModuleNav"; import { modules, lessonHref } from "@/data/curriculum"; import { ReadAloud } from "@/components/ReadAloud"; import { MarkComplete } from "@/components/Tracking";
// Full-width illustration placed inside a lesson body, right after the section it illustrates.
// Animated images (.webp/.gif) skip Next's optimizer, which would flatten them to one frame.
function LessonFigure({src,alt,caption}:{src:string;alt:string;caption?:string}){return <figure className="lesson-figure"><Image src={src} alt={alt} width={1672} height={941} unoptimized={/\.(webp|gif)$/.test(src)} sizes="(max-width: 900px) 100vw, 760px" style={{width:"100%",height:"auto",borderRadius:12,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}}/>{caption&&<figcaption>{caption}</figcaption>}</figure>}
const content:Record<string,{kicker:string;title:string;lead:string;body:React.ReactNode;image?:string;image2?:string;image3?:string}>={
 "why-we-hesitate":{kicker:"Lesson 1 of 6",title:"Why We Hesitate",lead:"Call reluctance is not laziness. It is your brain trying to protect you from an uncertain social outcome.",body:<><h2>The pause before the call</h2><p>You know who to call. You know roughly what to say. Yet suddenly checking email, researching the account one more time, or reorganizing the CRM feels urgent. That is the avoidance loop at work.</p><LessonFigure src="/lesson-why-we-hesitate.png" alt="A rep at his desk while email, research and CRM tasks pull his attention away from the call" caption="Email, one more round of research, CRM cleanup: anything but the dial." /><blockquote>Call reluctance grows when avoiding the call produces immediate relief.</blockquote><h2>What is really happening?</h2><p>Your brain often treats a cold call as a social threat: you might be dismissed, challenged, or exposed as not knowing every answer. Avoidance briefly removes that discomfort, which teaches your brain to repeat the behavior.</p><h2>Why it actually hurts</h2><p>This isn&apos;t just a figure of speech. Neuroscientists Naomi Eisenberger and Matthew Lieberman found that social rejection activates the dorsal anterior cingulate cortex&mdash;the same brain region that processes physical pain. A dismissive &ldquo;not interested&rdquo; registers, briefly, as something closer to an injury than an inconvenience, which is part of why one bad call can sting more than the facts of the situation justify.</p><LessonFigure src="/lesson-why-we-hesitate-2.png" alt="Illustration of social rejection and physical pain lighting up the same region of the brain" caption="Rejection and physical pain activate the same brain region." /><p>It also gets weighted unfairly. Psychologist Roy Baumeister and colleagues documented what they called the negativity bias: across dozens of studies, people consistently give a single negative event more psychological weight than several neutral or positive ones. Nine calls that went fine and one that went badly rarely feel like a 9-to-1 day&mdash;they feel like &ldquo;a bad day,&rdquo; because the one bad call is doing most of the emotional work.</p><h2>The first reframe</h2><p>Your job is not to control whether a merchant is interested. Your job is to create enough relevant conversations to find the merchants who have a problem you can help solve. Knowing the sting is a documented, universal brain response&mdash;not a personal weakness&mdash;is itself part of what makes it easier to dial through.</p></>},
 "fear-of-rejection":{kicker:"Lesson 2 of 6",title:"Fear of Rejection",lead:"A merchant rejecting a conversation is responding to timing, relevance, and circumstance—not issuing a verdict on you.",body:<><h2>Rejection feels personal</h2><p>Cold calling puts your request directly in front of another person. When they say no, your nervous system can interpret it as social rejection even though the merchant is making a business decision with limited information.</p><blockquote>“No” is an outcome from one moment—not a measurement of your worth or potential.</blockquote><h2>Separate identity from outcome</h2><p>Instead of saying “I was rejected,” use precise language: “That merchant did not agree to a conversation today.” Accuracy matters. It keeps one call from becoming a story about your ability.</p><h2>Why the reframe changes the feeling, not just the words</h2><p>This isn&apos;t simply positive self-talk. Psychologist James Gross&apos;s research on emotion regulation shows that cognitive reappraisal&mdash;deliberately changing how you describe or interpret a situation&mdash;measurably reduces activity in the brain&apos;s threat-response circuitry, compared with suppressing the feeling or just gritting through it. Swapping &ldquo;I got rejected&rdquo; for &ldquo;that merchant didn&apos;t agree to a conversation today&rdquo; isn&apos;t a euphemism; it&apos;s a documented technique for lowering the actual emotional charge of the event, not just how you talk about it afterward.</p><h2>Measure the controllable</h2><p>You control preparation, dials, tone, questions, follow-up, and reflection. You do not control timing, current contracts, competing priorities, or another person&apos;s mood.</p><LessonFigure src="/lesson-fear-of-rejection.png" alt="A rep surrounded by what he controls (notes, dials, questions, follow-up) while timing, contracts and mood sit outside the circle" caption="Inside the circle: what you control. Outside it: what you don't." /></>},
 "sounding-inexperienced":{kicker:"Lesson 3 of 6",title:"Fear of Sounding Inexperienced",lead:"Sounding unsure on a call almost never comes from a knowledge gap—it comes from talking in generalities instead of specifics you actually trust.",body:<><h2>It is not what you know, it is what you can say out loud</h2><p>Most reps who freeze up on rate or technical questions actually know the material. The freeze happens live, on the phone, when a merchant asks something pointed and the rep reaches for an answer they have never said out loud before. Silence and hedging read as inexperience even when the underlying knowledge is fine.</p><blockquote>Confidence on a call is a rehearsal problem, not a competence problem.</blockquote><h2>Two well-documented effects at work</h2><p>The freeze itself has a name. Psychologists Pauline Clance and Suzanne Imes described the impostor phenomenon in 1978&mdash;the persistent feeling of being a fraud despite clear evidence of competence. It shows up constantly in strong performers, not just beginners, which is why tenure alone rarely makes it disappear on its own.</p><p>The fix has research behind it too. The testing effect&mdash;demonstrated repeatedly in memory research by Henry Roediger and Jeffrey Karpicke&mdash;shows that actually retrieving and saying information out loud builds far more durable, fluent recall than passively re-reading or reviewing it silently. Saying your answer to a rate objection out loud once, before you need it, is doing real cognitive work, not just “practicing.”</p><h2>Have one real number ready</h2><p>Before you dial, have at least one concrete figure in your pocket—an average effective rate, a typical savings range, a common statement line item merchants overpay on. One real number said plainly does more for your credibility than a well-organized script.</p><h2>Say it before you need it</h2><p>Practice your answer to the 2-3 questions merchants ask most—rates, contracts, switching hassle—out loud, before the call, not while composing it live for the first time in front of a prospect. The goal is not memorization, it is removing the moment of surprise.</p><LessonFigure src="/lesson-sounding-inexperienced.png" alt="A rep rehearsing rate, contract and switching answers out loud before making the call" caption="Say the answers out loud before the call, then take the call." /></>},
 "avoidance-loop":{kicker:"Lesson 4 of 6",title:"The Avoidance Loop",lead:"Avoiding a call gives you real, immediate relief—which is exactly what trains your brain to keep avoiding it.",body:<><h2>How the loop runs</h2><p>A dial feels uncertain, so you do something that feels productive instead: more research, CRM cleanup, one more warm callback. The discomfort drops immediately. Your brain logs that relief as a reward, and the substitute behavior gets a little more automatic the next time a hard call is due.</p><LessonFigure src="/lesson-avoidance-loop-2.png" alt="The avoidance loop: research, reorganizing, an easy warm call and relief, broken by a 5-minute timer that leads straight to a dial" caption="The loop runs on relief. A 5-minute cap breaks it." /><blockquote>The loop is not broken by willpower—it is broken by removing the substitute behaviors it runs on.</blockquote><h2>Why this isn&apos;t a willpower problem</h2><p>This exact mechanism has a name and a long research history. Psychologist O. Hobart Mowrer&apos;s two-factor theory of avoidance learning (1947) explains how avoidance behavior gets reinforced by the relief it produces, regardless of whether the feared outcome was ever likely to happen. The relief is real and immediate; the threat it&apos;s avoiding is often exaggerated or gone. That mismatch is exactly why avoidance can quietly grow stronger over time even as the actual risk of a bad call stays low.</p><p>It&apos;s the same mechanism clinical psychologists target in exposure therapy for anxiety and phobias: preventing the avoidance response, even briefly, is what lets the brain recalibrate how threatening a situation actually is. A cold call is a much lower-stakes version of the same pattern.</p><h2>Recognize the substitutes</h2><p>Research past a 5-minute cap, reorganizing a list that was already fine, or working the same three easy contacts instead of the cold ones—none of it is a dial, no matter how busy it feels.</p><h2>Break it with a hard boundary, not more motivation</h2><p>Time-box research to 5 minutes before the first attempt. Dial before you open email or touch the CRM. Put your coldest, highest-friction leads first in the day, when avoiding them takes the most active effort to justify.</p><LessonFigure src="/lesson-avoidance-loop.png" alt="Email and research locked while a 5-minute timer sends the rep straight to his coldest lead" caption="Lock the substitutes, cap research at 5 minutes, and call the coldest lead first." /></>},
 "the-call-block":{kicker:"Lesson 1 of 6",title:"Building Your Call Block",lead:"“I’ll make some calls today” is the easiest plan in the world to skip. A call block is a scheduled window with a defined job, not a vague intention.",body:<><h2>Three blocks, three jobs</h2><p>Split the day instead of leaving it open-ended. An AM block (60–90 minutes) works your freshest, coldest, highest-friction leads first, while willpower is highest. A midday block (30–45 minutes) is for callbacks and follow-ups only—no fresh prospecting. A PM block (60–90 minutes) is a second pass on the AM list: decision-makers who didn’t answer the first time often answer the second.</p><LessonFigure src="/lesson-the-call-block.png" alt="Three call blocks across the day: cold leads in the morning, callbacks at midday, a second pass in the afternoon" caption="AM, midday and PM blocks each have one job." /><blockquote>A call block is an appointment with yourself. You wouldn’t skip a meeting with your manager because the first ten minutes felt uncomfortable.</blockquote><h2>Protect the block</h2><p>Nothing else happens inside it—not email, not CRM cleanup, not “quick research.” Those are legitimate tasks, but they belong before or after the block, never inside it. The block only has one job: dialing.</p><h2>Use the Pomodoro Method inside longer blocks</h2><p>A 60–90 minute block of nothing but cold dials is a lot to sustain at full focus. Split it into 25-minute dial sprints with a strict 5-minute break between them—the classic Pomodoro structure. Set a timer, dial with full attention until it rings, then actually step away for the break instead of letting it bleed into a sixth call.</p><LessonFigure src="/lesson-the-call-block-2.png" alt="A 25-minute dial sprint, a 5-minute break, then another 25-minute sprint" caption="25-minute sprints with a real 5-minute break between them." /><blockquote>The break is what makes the next sprint full-intensity again. Skipping it to squeeze in one more call is how a 90-minute block quietly turns into 40 minutes of real focus and 50 minutes of fading energy.</blockquote><h2>Why the sprint structure works</h2><p>This isn&apos;t just a productivity trend. Sustained-attention research dating back to N.H. Mackworth&apos;s original radar-operator studies has repeatedly found that vigilance on a monotonous, effortful task reliably declines within about 20&ndash;30 minutes&mdash;a pattern researchers call the vigilance decrement. A scheduled break isn&apos;t a reward for reaching the timer; it&apos;s what lets attention actually reset before it decays further.</p><p>Two or three sprints comfortably fill an AM or PM block, with a natural, built-in stopping point if something urgent comes up—far easier to protect than one long undifferentiated stretch.</p></>},
 "setting-your-number":{kicker:"Lesson 2 of 6",title:"Setting a Real Daily Target",lead:"A goal that depends on how the morning went isn’t a goal—it’s a mood. Set the number before you dial, from your list size, not your feelings.",body:<><h2>Why “make some calls” fails</h2><p>A target with no number attached quietly shrinks the moment the first few calls go badly. There’s nothing to hold you to, so the day drifts into other tasks that feel productive without being a dial.</p><h2>Set it from the list, not the mood</h2><p>Pick a minimum daily dial count sized to your actual list—enough to reach every priority lead this week without over-calling anyone. Write it down before the first dial, and commit to it even if the first ten calls go badly.</p><LessonFigure src="/lesson-setting-your-number.png" alt="A rep turns his lead list into a daily target of 30 dials and writes the number down, ignoring his mood" caption="Size the number from your list, write it down, and leave your mood out of it." /><blockquote>The 11th call doesn’t know about the first 10. Whether it goes well has nothing to do with how the morning felt.</blockquote><h2>Vague goals reliably underperform specific ones</h2><p>This is one of the most replicated findings in organizational psychology. Edwin Locke and Gary Latham&apos;s goal-setting theory, built on decades of studies across a wide range of tasks, consistently found that specific, measurably-defined goals produce higher effort and performance than vague &ldquo;do your best&rdquo; goals&mdash;even when the specific goal is demanding. &ldquo;Make some calls&rdquo; is a do-your-best goal. A written number is not.</p><h2>Treat the number as non-negotiable</h2><p>A bad morning is a reason to keep the number, not shrink it—shrinking it on hard days is exactly how the number stops meaning anything.</p><LessonFigure src="/lesson-setting-your-number-2.png" alt="Call 11 of 30 with the target locked, after a string of no-answers" caption="Call 11 of 30. The target stays locked, whatever the first ten did." /></>},
 "the-precall-routine":{kicker:"Lesson 3 of 6",title:"A Pre-Call Routine That Removes Hesitation",lead:"Every decision you have to make right before dialing—who, what to say, whether you’re ready—is a fresh opening for hesitation. A routine removes the decisions.",body:<><h2>Hesitation lives in the gaps</h2><p>It’s rarely the call itself that gets skipped—it’s the ten seconds before it, where your brain gets a fresh chance to ask “am I really ready for this one?” The more decisions packed into that gap, the more chances to stall.</p><h2>The routine</h2><p>Run the same short sequence before every block, in the same order, so none of it requires a decision: pull today’s list and confirm the first name, glance at your answers to the 2–3 objections you hear most, say your opener out loud once, then dial immediately—no further prep after that.</p><LessonFigure src="/lesson-the-precall-routine.png" alt="The four-step pre-call routine: pull the list, glance at the 2-3 objection answers, say the opener out loud, then dial" caption="Pull the list, glance at your objection answers, say the opener out loud, dial." /><blockquote>A routine replaces willpower with habit. You don’t decide to start; you just run the sequence and the dial happens at the end of it.</blockquote><h2>Decision fatigue is real and measurable</h2><p>Roy Baumeister&apos;s research on ego depletion describes how the mental effort of making decisions draws down a limited resource over the course of a day. A striking real-world example: a 2011 study of Israeli parole judges found their rate of favorable rulings started high after each break, then dropped steadily toward zero as the session wore on, before jumping back up after the next break. Nothing about the cases changed&mdash;the judges&apos; capacity to weigh a fresh decision did.</p><LessonFigure src="/lesson-the-precall-routine-2.png" alt="A rep full of energy in the morning, drained and hesitating late in a session, then recharged after a short break" caption="Every decision draws down the tank. A routine and a real break refill it." /><p>A pre-call routine works the same way a scheduled break does for those judges: it removes decisions from the exact moments&mdash;right before a hard dial&mdash;when you have the least mental capacity left to make them well.</p><h2>Keep it identical every time</h2><p>The value is in the repetition, not the content—changing the routine daily just recreates the decision-making it’s meant to remove.</p></>},
 "activity-vs-outcome":{kicker:"Lesson 4 of 6",title:"Track Activity, Not Just Outcomes",lead:"A closed deal tells you what worked weeks ago. Dials, connects, and conversations tell you what’s happening today—while there’s still time to fix it.",body:<><h2>Outcomes lag activity</h2><p>Deals closed this week reflect calls made weeks ago, not today’s effort. If you only track outcomes, a real problem—reluctance, a bad list, a broken opener—can run for weeks before the numbers show anything is wrong.</p><LessonFigure src="/lesson-activity-vs-outcome.png" alt="A rep's dashboard showing 24 dials, 6 conversations and 3 next steps, leading weeks later to a closed deal" caption="Dials, conversations and next steps today. The closed deal shows up weeks later." /><h2>What to log, and when</h2><p>Dials attempted, conversations had, and next steps set are all controllable today. Log them in the CRM in real time, right after each call—not from memory at the end of the day, when half of it gets lost or rounded up.</p><blockquote>Logging a call takes 30 seconds. It is not the task you’re avoiding by putting it off—it just feels that way in the moment.</blockquote><h2>Leading indicators, not just lagging ones</h2><p>Performance management draws a standard distinction between lagging indicators&mdash;results you can only measure after the fact, like closed deals&mdash;and leading indicators&mdash;behaviors today that predict those results later, like dials and conversations. Psychologists Edward Deci and Richard Ryan&apos;s self-determination theory supplies the motivational half of the story: goals built around effort and behavior you actually control sustain motivation far better over time than goals tied only to outcomes you don&apos;t fully control.</p><p>Tracking dials and conversations isn&apos;t a consolation prize for not having closed deals yet&mdash;it&apos;s the metric that&apos;s still actually yours to move today.</p><h2>Why this matters beyond you</h2><p>Consistent activity logging is also what lets a manager coach the actual problem instead of guessing—see the Manager view for how this data turns into specific coaching, not vague encouragement.</p><LessonFigure src="/lesson-activity-vs-outcome-2.png" alt="A rep logs a call in 30 seconds while his manager reviews the same activity data to coach him" caption="Log each call in 30 seconds, and your manager can coach the real problem." /></>},
 "the-first-ten-seconds":{kicker:"Lesson 1 of 4",title:"The First Ten Seconds",lead:"Before a merchant hears your offer, they’ve already decided whether you’re worth another thirty seconds. The opener’s only job is to win that decision.",body:<><h2>What the merchant is deciding</h2><p>When a restaurant owner or store manager picks up, they’re answering three quick questions: Who is this? Why are they calling me? Is this worth another thirty seconds? If your first ten seconds don’t answer all three, the answer to the last one defaults to no.</p><LessonFigure src="/lesson-the-first-ten-seconds.png" alt="A merchant weighing three checkpoints on a cold call: who is this, why are they calling my business, and is it worth another thirty seconds" caption="Who is this? Why me? Is it worth thirty more seconds? Answer all three or the answer is no." /><blockquote>The opener doesn’t sell anything. It earns the next thirty seconds.</blockquote><h2>Snap judgments are fast, and they stick</h2><p>Psychologists Nalini Ambady and Robert Rosenthal found that people who watched just a few seconds of silent video of a teacher formed impressions that closely matched the end-of-semester ratings from students who had spent months in that class. Their 1993 study used clips as short as six seconds. Judgments formed in the first moments aren’t random, and they’re hard to shift afterward. On a cold call the merchant has even less to go on: your voice, your first sentence, and whether it sounds like it’s about them.</p><h2>A three-part opener</h2><p>Keep the structure fixed so you’re never improvising the part that matters most. First, who you are, in one breath: your first name and company. Second, why you’re calling them specifically: a real reason tied to their business. Third, a short question that’s easy to answer.</p><p>For example: “Hi Maria, it’s David with BytePOS. I’m calling because you opened the Atlantic Avenue location last month, and owners at that stage often end up running two different card systems. Did you keep the same processor for both?” That takes about twelve seconds, and every part answers one of the merchant’s three questions.</p><LessonFigure src="/lesson-the-first-ten-seconds-anim.webp" alt="Animated: a rep delivers his opener to a restaurant owner as it moves through who he is, a reason tied to the store, and a short question, inside a ten-second timer" caption="Who you are, why them, one easy question: about ten seconds." /><h2>What to cut</h2><p>“How are you today?” from a stranger tells the merchant it’s a sales call before you’ve said why you’re calling. So does a long company introduction. Everything before your reason is time the merchant spends deciding without the one piece of information that could make them say yes.</p></>},
 "a-reason-about-them":{kicker:"Lesson 2 of 4",title:"Give Them a Reason That’s About Them",lead:"“We help businesses save on processing” could be said to anyone, so it sounds like it’s being said to everyone. A specific reason tells the merchant this call is actually about them.",body:<><h2>Why a reason works at all</h2><p>In a classic 1978 study, Harvard psychologist Ellen Langer and her colleagues had someone ask to cut in line at a copy machine. With no reason given, 60% of people let them. Adding a reason, “because I’m in a rush,” raised that to 94%. Even a nearly empty reason, “because I have to make copies,” got 93%. For small requests, people respond to the presence of a reason almost automatically.</p><h2>On a cold call, the reason has to hold up</h2><p>The copy-machine requests were tiny and the stakes were low. A merchant getting their fifth processing call of the week is paying closer attention, and a generic reason gets filed with the other four. Giving a reason earns you the benefit of the doubt. A specific reason keeps it.</p><LessonFigure src="/lesson-a-reason-about-them.png" alt="A generic pitch broadcast to many restaurants and ignored, next to one specific reason routed to a single restaurant with two disconnected card systems" caption="A pitch sent to everyone gets filed with the others. A reason about one merchant gets heard." /><blockquote>If your reason would work for any business on your list, it isn’t a reason. It’s a category.</blockquote><h2>Where specific reasons come from</h2><p>You don’t need deep research, and the 5-minute cap from Module 1 still applies. One real observation is enough: a new or second location, a recent ownership change, a liquor license application, reviews that mention “cash only” or a card reader that’s always down, a cash-discount notice on the menu, or an older terminal visible in photos. For leads that came from a new-opening or permit signal, the signal that put them on your list is usually the reason.</p><h2>Turn the observation into a likely problem</h2><p>The observation on its own isn’t the reason. What it usually means for the merchant is. “You opened a second location” becomes “owners at that stage often end up with two systems that don’t talk to each other.” Say it as something that’s common, not something you’re accusing them of. You’re offering a guess they can confirm or correct, and either answer keeps the conversation going.</p><LessonFigure src="/lesson-a-reason-about-them-2.png" alt="A rep noticing a restaurant has two locations whose POS systems aren't connected" caption="The observation: a second location. The likely problem: two systems that don't talk to each other." /></>},
 "drop-the-apology":{kicker:"Lesson 3 of 4",title:"Drop the Apology and the Script Voice",lead:"“Sorry to bother you, I’ll be really quick” tells the merchant your call is an interruption before they’ve decided whether it is one.",body:<><h2>Apologizing for the call frames the call</h2><p>Openers like “sorry to bother you,” “I know you’re busy,” or “I’ll just take a second” are meant to sound polite. What they actually communicate is that you consider this call an imposition, and they invite the merchant to agree. You’re a professional calling about something that might help their business. Say so plainly and let them decide.</p><LessonFigure src="/lesson-drop-the-apology.png" alt="Split scene: an apologetic rep reading a script meets a closed-off merchant; the same rep speaking plainly with his notes gets an engaged merchant" caption="Reading an apology invites a no. Speaking plainly about their business invites a reply." /><blockquote>Polite and apologetic aren’t the same thing. Be the first without the second.</blockquote><h2>Plain words sound more credible, not less</h2><p>Psychologist Daniel Oppenheimer’s research on processing fluency found that writing full of unnecessarily complex words was judged to come from less intelligent authors than the same ideas written plainly. His 2006 paper made the point in its own title: “Consequences of Erudite Vernacular Utilized Irrespective of Necessity.” The same applies out loud. “We provide comprehensive, end-to-end payment solutions” is harder to process than “we set up card processing and POS systems for restaurants,” and whatever is harder to process comes across as less credible.</p><h2>Script voice is a delivery problem</h2><p>Reps who read an opener sound like they’re reading: an even pace, no pauses, and the same rise at the end of every sentence. Merchants hear that pattern all day and tune it out. The fix isn’t to drop the structure. It’s to know the three parts well enough to say them in your own words. That’s the rehearsal effect from Module 1: say your opener out loud until it sounds like something you’d actually say.</p><LessonFigure src="/lesson-drop-the-apology-2.png" alt="A flat, monotone script waveform fading out above a natural waveform with pauses, as a rep practices his opener out loud" caption="Script voice runs flat and even. Your own words have pauses and land." /><h2>End statements like statements</h2><p>Let your voice come down at the end of your name and your reason. A rising tone turns “It’s David with BytePOS” into a question, as if you’re asking permission to be on the call. Save the rise for the one real question at the end of your opener.</p></>},
 "ask-for-the-next-30-seconds":{kicker:"Lesson 4 of 4",title:"Ask for the Next 30 Seconds",lead:"The opener ends with a question the merchant can answer in a few words. The goal isn’t the appointment yet. It’s a conversation that keeps going.",body:<><h2>Close the opener with an easy question</h2><p>A good closing question is specific, about their business, and answerable without much thought: “Did you keep the same processor for both locations?” or “Are you still on the terminal that came with the space?” Avoid questions that are really a pitch, like “Would you like to save money on processing?”, and questions that invite a reflex no, like “Do you have a minute?”</p><blockquote>Ask something they can answer in five words. Every answer tells you where to go next.</blockquote><h2>Small yeses make bigger ones easier</h2><p>In a well-known 1966 study, psychologists Jonathan Freedman and Scott Fraser asked homeowners to put a large, unattractive “Drive Carefully” sign on their front lawn. Only about 17% agreed. But among homeowners who had agreed two weeks earlier to a much smaller request, displaying a three-inch safe-driving sign, about 76% agreed to the big one. This foot-in-the-door effect is why the opener aims small. A merchant who has answered one easy question about their setup has already started a conversation, and continuing it is the natural next step.</p><LessonFigure src="/lesson-ask-for-the-next-30-seconds.png" alt="A merchant answers one easy question about their terminal, the conversation continues, and it ends in a booked appointment" caption="One easy answer, then a conversation, then the appointment." /><h2>“Who is this?” and “What’s this about?”</h2><p>These aren’t objections. They’re the merchant asking for the things your opener should have covered. Answer directly and briefly, repeat your reason, and ask your question again. Getting defensive, or starting over with a longer pitch, turns a request for clarity into a reason to hang up.</p><h2>Know when the opener worked</h2><p>The opener worked if the merchant is talking about their business, even if what they say is “we’re happy with what we have.” That’s a conversation, and it’s your handoff to the rest of the call. The opener only failed if the call ended before they said anything about their business at all.</p><LessonFigure src="/lesson-ask-for-the-next-30-seconds-2.png" alt="A restaurant owner on the phone talking about his two locations while the rep listens, with a thirty-second timer between them" caption="The merchant is talking about their business. The opener did its job." /></>},
 "every-vertical-has-its-own-pain":{kicker:"Lesson 1 of 4",title:"Every Vertical Has Its Own Pain",lead:"A restaurant owner and an HVAC contractor both take cards, but they lose sleep over completely different things. Relevance starts with knowing which problems belong to which business.",body:<><h2>“Payments” isn’t one problem</h2><p>Reps who pitch the same benefits to every merchant are pitching the product, not the business. Lower rates and faster deposits matter to everyone, which is exactly why they don’t make anyone lean in. What earns attention is the problem that business runs into every week, said in a way that tells the owner you already understand how their day works.</p><blockquote>Rates are what every merchant has in common. Their real problem is what makes them different.</blockquote><h2>What each vertical tends to care about</h2><p><b>Restaurants:</b> tips and tip adjustments, splitting checks, speed at the counter during a rush, online ordering, and the commissions third-party delivery apps take, often 15% to 30% of an order. <b>Retail:</b> inventory that matches what actually sold, chargebacks, seasonal swings in volume, gift cards, and reporting across more than one location. <b>Service businesses</b> like salons, auto shops and contractors: getting paid on the job or in the field, cards on file, deposits and no-show fees, and chasing unpaid invoices. <b>E-commerce:</b> checkout friction, fraud and chargebacks, and card-not-present pricing, which usually runs higher than card-present.</p><p>Treat these as starting guesses, not facts about the merchant you’re calling. Their job is to make your first question a good one.</p><LessonFigure src="/lesson-every-vertical-has-its-own-pain.png" alt="A rep studying four panels: a busy restaurant, a clothing store, a contractor at his van, and an online shopper, each with its own list of problems" caption="Four verticals, four different problems. Start with the one that fits." /><h2>Timing is part of relevance</h2><p>Calling a restaurant at 12:15 or 6:30 tells the owner you don’t know their business before you’ve said a word. Most restaurants are easiest to reach in the mid-afternoon lull, roughly 2 to 4 p.m. Retail managers are often freer right after opening, before foot traffic builds. Contractors and other field businesses are usually reachable early, before they head out, or at the end of the day. Matching your call block to the vertical is the cheapest relevance you’ll ever get.</p><LessonFigure src="/lesson-every-vertical-has-its-own-pain-2.png" alt="A timeline of the day: a contractor reached early, a store manager after opening, a restaurant owner in the mid-afternoon lull, with the lunch and dinner rushes crossed out" caption="Call each vertical when they can actually talk: early for contractors, after opening for retail, 2 to 4 p.m. for restaurants." /><h2>Build a one-line cheat sheet per vertical</h2><p>For each vertical on your list, write one line: the two problems that come up most, and the best time to call. Keep it next to your pre-call routine from Module 2. It turns “what do I say to a salon?” from something you improvise live into something you decided ahead of time.</p></>},
 "speak-in-their-numbers":{kicker:"Lesson 2 of 4",title:"Speak in Their Numbers",lead:"“We can save you money” is abstract. “On a $40 average ticket, that’s about 30 cents a transaction” is something the owner can picture. Concrete beats clever.",body:<><h2>Concrete sounds true</h2><p>Psychologists Jochim Hansen and Michaela Wänke found in 2010 that people rated the same claim as more likely to be true when it was written in concrete language than in abstract terms. Nothing about the facts changed, only how easy they were to picture. On a cold call, abstract benefits like “efficiency,” “savings” and “better experience” slide straight past the merchant. Specifics stick, because the merchant can check them against their own business in their head.</p><blockquote>If the owner can’t picture it, they won’t believe it.</blockquote><LessonFigure src="/lesson-speak-in-their-numbers.png" alt="A rep turning a restaurant's $40 average ticket into a concrete figure of 30 cents per transaction while the owner listens" caption="“Savings” slides past. “About 30 cents on a $40 ticket” is something the owner can check in their head." /><h2>Use the units they already track</h2><p>Every vertical measures itself differently. Restaurants think in covers, average ticket and table turns. Retail thinks in average basket, transactions per day and shrink. Service businesses think in jobs per week and days until they get paid. E-commerce thinks in orders, conversion rate and chargebacks. Translate what you offer into their unit: not “faster funding” but “the money from Friday’s jobs in your account Saturday instead of Tuesday.”</p><h2>Small, honest math beats big claims</h2><p>You rarely know a merchant’s real numbers on the first call, and inventing them costs you credibility. Use ranges and ask them to fill in the gap: “Most places your size run somewhere around 800 to 1,200 transactions a month. Is that close for you?” Their answer gives you a real number to work with, and asking shows you understand how their business is measured. Never promise a specific savings figure before you’ve seen a statement.</p><h2>One number, then stop</h2><p>A single concrete figure lands. Three in a row sound like a pitch deck. Pick the one number that matters most to this vertical, say it plainly, and let the merchant react. If it’s wrong for them, they’ll correct you, and the correction is the start of discovery.</p><LessonFigure src="/lesson-speak-in-their-numbers-2.png" alt="Four panels for a restaurant, a store, a contractor and an online shop, each with its own numbers and one highlighted as the number that matters most" caption="Every vertical has its own numbers. Pick the one that matters most to this merchant and stop there." /></>},
 "lead-with-a-business-like-theirs":{kicker:"Lesson 3 of 4",title:"Lead With a Business Like Theirs",lead:"Merchants don’t want to be your first. A real example of a business like theirs does more than any feature list, as long as it’s true.",body:<><h2>People follow people like them</h2><p>In a 2008 study, Noah Goldstein, Robert Cialdini and Vladas Griskevicius tested hotel signs asking guests to reuse their towels. The standard environmental message got about 35% of guests to reuse towels. A message saying most guests at the hotel reused theirs raised that to about 44%. Saying most guests who had stayed in that same room did so pushed it to about 49%. The closer the comparison group was to the guest, the stronger the effect.</p><blockquote>“Businesses like yours” beats “businesses.” “The pizzeria two miles from you” beats both.</blockquote><h2>Make the comparison close</h2><p>The same principle applies on the phone. “We work with thousands of merchants” is the generic hotel sign. “We set up two other family-owned taquerias in Jacksonville this year” is the same-room sign. Match on what the owner identifies with: the type of business, the size, the city, or the situation they’re in, like a second location or a recent ownership change.</p><LessonFigure src="/lesson-lead-with-a-business-like-theirs.png" alt="A rep mentions a nearby taqueria to a taqueria owner, who looks interested" caption="Not “thousands of merchants.” A business like theirs, close by." /><h2>Only ever use real examples</h2><p>This works because it’s true. If you invent a customer, a result, or a nearby business that doesn’t exist, you’re lying to the merchant, and one follow-up question exposes it. Keep a short list of real accounts you or your team have set up, by vertical and area, and what changed for them in plain words. Check with your manager before you name a customer. When you don’t have a close match, describe the situation honestly: “Owners who just opened a second spot usually tell us the hardest part is…”</p><LessonFigure src="/lesson-lead-with-a-business-like-theirs-2.png" alt="Before a call to a salon owner, a rep picks a real, verified salon customer as his example and rejects an invented one" caption="Match on a real customer, never an invented one." /><h2>Keep it to one sentence</h2><p>The example supports your reason for calling. It doesn’t replace your question. One sentence, then back to the merchant: “We set up a salon on Atlantic Avenue last spring that was losing a few hundred a month to no-shows. Are you taking deposits when people book?”</p></>},
 "fit-the-software-they-run":{kicker:"Lesson 4 of 4",title:"Integrated Payments: Fit the Software They Already Run",lead:"Many merchants don’t think of themselves as buying payments. They think of themselves as running their salon software, their practice system, or their POS. Start there.",body:<><h2>The software comes first</h2><p>Salons book in scheduling software, auto shops write tickets in shop-management systems, restaurants live in their POS, and online stores run on their e-commerce platform. For these owners, payments are one feature inside a tool they already depend on. When payments are built into that tool, sales, tips, refunds and deposits reconcile on their own. When they aren’t, someone ends up retyping totals into a terminal and matching reports at the end of the day.</p><LessonFigure src="/lesson-fit-the-software-they-run.png" alt="A salon owner points to her booking software, one of several business apps (salon, auto shop, restaurant, retail), each with payments built in" caption="Start with the software they already run. Payments are one feature inside it." /><blockquote>Ask what software they run before you mention what you sell.</blockquote><h2>Why switching feels expensive</h2><p>Economists William Samuelson and Richard Zeckhauser coined the term status quo bias in 1988, after finding that people disproportionately stick with whatever option they already have, even when an alternative is at least as good. For a merchant, the software they run every day is the status quo. A pitch that sounds like “replace your system” asks them to fight that bias. A pitch that works with their system doesn’t.</p><h2>Ask about the software first</h2><p>“What are you using for booking?” or “What POS are you on?” is easy to answer, specific, and tells you almost everything about where you fit. If your payments integrate with their software, lead with that: nothing new to learn, and no more double entry. If they don’t, be honest about what would change and what they would get in return. Don’t promise an integration you haven’t confirmed.</p><h2>Listen for double entry</h2><p>The clearest sign of an integration problem is manual work: “My front desk types the total into the card machine,” or “I match the deposits to the tickets every Friday.” When you hear it, repeat it back in their words and ask how long it takes. That time is the business case, and it came from the owner, not from you.</p><LessonFigure src="/lesson-fit-the-software-they-run-2.png" alt="Left: a salon front desk retyping a total into a card machine and matching reports that don't agree. Right: payments built into the salon software, reconciling on their own" caption="Double entry on the left, integrated payments on the right. The time it costs is the business case." /></>},
 "discovery-not-interrogation":{kicker:"Lesson 1 of 4",title:"Discovery Is Not an Interrogation",lead:"Once the merchant starts talking, it’s tempting to run down a checklist. Ten questions in a row feels like an audit, and merchants end audits quickly.",body:<><h2>Why the checklist backfires</h2><p>On a cold call you haven’t earned much patience yet. Rapid-fire questions about their processor, their rates, their volume and when their contract ends make the merchant feel like they’re being qualified, which they are. Answers get shorter, and “just send me something” shows up soon after. Every question costs the merchant a little time and attention. They’ll keep answering only as long as the conversation gives them something back.</p><blockquote>Ask questions the merchant is glad you asked, not questions they’re putting up with.</blockquote><LessonFigure src="/lesson-discovery-not-interrogation.png" alt="Split scene: a rep firing a clipboard's worth of questions at a restaurant owner who sits with arms crossed, and the same rep asking one question with context while the owner leans in" caption="A checklist feels like an audit. One question with a reason behind it feels like a conversation." /><h2>Give a little before you ask</h2><p>Put a short piece of context in front of the question: “A lot of salons we talk to lose real money to no-shows. Do you take a card to hold appointments?” The context tells the owner why you’re asking, shows you know their world, and makes the question feel like it’s about their business instead of your form. It’s the same idea as the reason in your opener from Module 3.</p><h2>One question, then quiet</h2><p>Ask one question at a time. “Who do you process with, how long have you been with them, and are you happy?” lets the merchant pick the easiest part and skip the rest. After you ask, stop talking. A two-second pause feels long to you and normal to them, and the answer that comes after it is usually the more honest one.</p><h2>Keep it short on the phone</h2><p>A cold call isn’t the place for a full needs analysis. Three to five good questions is plenty. You’re trying to learn whether a meeting is worth both of your time, not everything about the business. The deeper discovery is what the appointment is for.</p></>},
 "ask-about-impact":{kicker:"Lesson 2 of 4",title:"Ask About Impact, Not Just Setup",lead:"“Who do you process with?” tells you their setup. “What happens when the card reader goes down on a Saturday?” tells you what the setup costs them. The second kind of question is where value comes from.",body:<><h2>What the research found</h2><p>Neil Rackham and his team at Huthwaite studied more than 35,000 sales calls over twelve years and published the results in <i>SPIN Selling</i> in 1988. Less successful sellers asked a lot of situation questions, the facts about the buyer’s current setup. More successful sellers asked fewer of those and spent more time on the buyer’s problems and what those problems led to. Buyers found long runs of situation questions tedious, because those questions serve the seller, not the buyer.</p><blockquote>Setup questions are for you. Impact questions are for them.</blockquote><LessonFigure src="/lesson-ask-about-impact.png" alt="A rep on a call with a restaurant owner, with panels showing a working terminal, the card reader failing, and a packed Saturday line of frustrated customers" caption="The terminal is the setup. The Saturday line when it goes down is the impact." /><h2>Three kinds of questions</h2><p><b>Setup</b> questions cover how they take payments today: processor, POS, terminals, online checkout. <b>Problem</b> questions ask what’s frustrating, slow or breaking. <b>Impact</b> questions ask what that problem costs in time, money or customers. A contractor example: “How long does it usually take to get paid once a job’s done?” is a problem question. “When it takes three weeks, what does that do to how you pay your crew and buy materials?” is an impact question. A restaurant example: “How much of your takeout comes through the delivery apps instead of your own site?” followed by “What does their cut add up to in a typical month?”</p><LessonFigure src="/lesson-ask-about-impact-2.png" alt="A rep talking with a contractor beside a work van, with panels tracing a finished job, a waiting invoice, a crew waiting to be paid, and materials on hold" caption="A slow payment isn’t just a date on an invoice. Ask what it does to the crew and the next job." /><h2>Do the setup homework before you dial</h2><p>A lot of setup questions can be answered before the call. The merchant’s website often shows their online ordering or booking provider, how many locations they have, and whether they sell online. Each fact you find is one less question you have to spend on the phone, and it frees the conversation for the questions that matter. Add a quick look-up to your pre-call routine from Module 2.</p><h2>Don’t lead the witness</h2><p>Impact questions aren’t traps. “Wouldn’t you agree you’re probably overpaying?” is a pitch with a question mark on the end, and merchants hear it that way. Ask honestly and accept the answer, including “It’s actually fine.” A merchant without a real problem is useful information too. It saves you an appointment that wasn’t going anywhere.</p></>},
 "follow-the-answer":{kicker:"Lesson 3 of 4",title:"Follow the Answer",lead:"The best discovery question usually isn’t on your list. It’s the one you build from what the merchant just said.",body:<><h2>Follow-up questions make you more likable</h2><p>In a 2017 study in the <i>Journal of Personality and Social Psychology</i>, Karen Huang, Alison Wood Brooks and colleagues at Harvard analyzed live conversations and found that people who asked more questions were liked more by the people they talked with. The effect came mostly from follow-up questions, the ones that build on what the other person just said. A follow-up shows you were listening in a way no scripted question can.</p><blockquote>A follow-up question is proof you were listening.</blockquote><h2>Three follow-ups that work almost anywhere</h2><p><b>Clarify their words:</b> “What do you mean by ‘all over the place’?” <b>Size it:</b> “How often does that happen?” <b>Get the history:</b> “What have you tried so far?” For example, if a store owner says the fees are all over the place, don’t move on to your next question. Ask: “All over the place how? Different every month, or just higher than you expected?” Their answer tells you far more than the question you were about to ask.</p><LessonFigure src="/lesson-follow-the-answer.png" alt="A store owner on a video call describing tangled, confusing fees while the rep branches the answer into three follow-ups: clarify, how often, and what they've tried" caption="“All over the place” is the start of the answer. Clarify it, size it, and ask what they’ve tried." /><h2>Listen for the loaded words</h2><p>Some words carry more than they seem to. “Honestly,” “nightmare,” “always” and “last time” usually point to a real frustration or a bad experience. So do mentions of a past processor, a new owner, a second location or a system they’re replacing. Jot them down as you hear them. They’re the best material you’ll get for a follow-up, and later for the appointment itself.</p><h2>Play it back before you move on</h2><p>Before you change topics, summarize what you heard in the merchant’s own words: “So if I’ve got this right, the fees jump around month to month and nobody’s ever explained why.” It checks your understanding, it gives them a chance to correct you, and it lets them hear their problem stated plainly. That summary is often the natural bridge to asking for the meeting.</p><LessonFigure src="/lesson-follow-the-answer-2.png" alt="A rep noting the merchant's loaded words in a notebook, playing them back, getting a confirmation, and moving to a calendar" caption="Write down the loaded words, play them back, and the summary becomes the bridge to the meeting." /></>},
 "what-the-appointment-needs":{kicker:"Lesson 4 of 4",title:"Know What the Appointment Needs",lead:"Discovery on a cold call has a finish line. Once you know there’s a real reason to meet and who needs to be in the room, stop digging and book it.",body:<><h2>The call isn’t the whole discovery</h2><p>The full analysis happens at the appointment, with a statement in hand and time to talk. On the call you only need enough to answer three questions: Is there a real reason to meet? Can this person make or influence the decision? What should the meeting cover? Keep digging past that point and you risk talking the merchant out of a meeting they were ready to take.</p><blockquote>Stop digging when you have a reason to meet. The rest of the discovery belongs in the meeting.</blockquote><h2>The short list</h2><p>Before you hang up, try to have four things. <b>A problem or goal in their words,</b> like the fees that jump around or the three-week wait to get paid. <b>Who decides:</b> the owner, a partner, a franchise’s corporate office, or the bookkeeper who reads the statements. <b>Anything that shapes timing,</b> such as a contract end date, an equipment lease, a new location opening, or a POS change. <b>A recent processing statement,</b> or at least agreement to have one ready for the meeting. Without a statement, nobody can honestly tell the merchant what they’d save.</p><LessonFigure src="/lesson-what-the-appointment-needs.png" alt="A rep with four checked-off cards for the problem, who decides, timing, and a statement, feeding into a calendar, with a shovel set down beside a check mark" caption="Problem, decision-makers, timing, statement. Once the short list is checked, put the shovel down and book it." /><h2>Ask about decisions without insulting anyone</h2><p>“Are you the decision-maker?” can sound like you’re checking whether they matter. Try “Besides you, who else would want to weigh in on something like this?” It gets the same information, respects the person you’re talking to, and helps you get everyone who matters into the meeting instead of hearing “I need to run it by my partner” afterward.</p><LessonFigure src="/lesson-what-the-appointment-needs-2.png" alt="A rep adding the merchant's partner to a video meeting and landing a confirmed time instead of a tentative one" caption="Ask who else should weigh in, and get them into the meeting instead of hearing about them afterward." /><h2>Be honest when there isn’t a fit</h2><p>Sometimes discovery shows there’s no meeting worth booking. They just signed a long contract with a steep cancellation fee, the problem you expected isn’t there, or the business is too small for what you offer. Say so, thank them, and set a date to check back. An honest “this isn’t the right time” builds the kind of reputation that gets you a warmer call later. Module 8 covers how to follow up without chasing.</p></>},
 "ask-for-the-meeting":{kicker:"Lesson 1 of 4",title:"Ask for the Meeting",lead:"Plenty of good calls end without an appointment for one reason: the rep never actually asked. Hinting and hoping feels polite. A clear, simple ask is what the merchant can say yes to.",body:<><h2>Hinting isn’t asking</h2><p>“So, maybe we could find some time at some point, if you’re open to it?” leaves the merchant to do the work of turning your hint into a plan, and most won’t. It also sounds like you aren’t sure the meeting is worth their time, so why should they be? When discovery has turned up a real reason to meet, say so and ask directly. You’ve earned it.</p><blockquote>If the meeting is worth their time, ask for it like it is.</blockquote><h2>Bridge from what they told you</h2><p>The best lead-in to the ask is the playback from Module 5: “So the fees jump around every month and nobody’s ever explained why.” Then connect it to the meeting: “That’s exactly what we can sort out in twenty minutes with one of your statements.” The merchant hears their own problem and a specific way to deal with it, which is a far better reason to meet than anything you could pitch.</p><LessonFigure src="/lesson-ask-for-the-meeting.png" alt="Split scene: a rep hinting vaguely while the owner looks unsure and the calendar fades away, and the same rep tying the owner's fee problem to a clear ask while a meeting lands on the calendar" caption="A hint leaves the owner to do the work. Their own problem, tied to a clear ask, gets the meeting on the calendar." /><h2>Say what the meeting is</h2><p>Tell them what will happen, how long it takes, and what they get out of it: “We’ll sit down for twenty minutes, go through your last statement line by line, and you’ll know exactly what you’re paying and whether there’s a better option. If you’re already in good shape, I’ll tell you.” A meeting with a clear purpose and a clear end is easy to agree to. A vague “chat about your processing” isn’t.</p><h2>Offer two times, not an open calendar</h2><p>“When works for you?” hands the merchant a decision they don’t want to make. In a 2000 study, Sheena Iyengar and Mark Lepper set up a jam-tasting table in a grocery store. When it showed 24 flavors, about 3 percent of the people who stopped went on to buy. When it showed 6, about 30 percent did. More choice made deciding harder. Offer two specific options instead: “Would Tuesday at 2:30 or Thursday at 10 work better?” If neither fits, they’ll tell you what does, and you’re still talking about when, not whether.</p><LessonFigure src="/lesson-ask-for-the-meeting-2.png" alt="A rep laying out the meeting as the owner's statement, twenty minutes, and a clear answer, then offering Tuesday at 2:30 or Thursday at 10 while the owner gives a thumbs up" caption="Say what the meeting is and how long it takes, then offer two specific times instead of an open calendar." /></>},
 "qualified-appointment":{kicker:"Lesson 2 of 4",title:"What Makes an Appointment Qualified",lead:"An appointment that goes nowhere costs everyone: the merchant’s time, the rep who runs it, and your credibility. A qualified appointment has a real reason, the right people, and the right material on the table.",body:<><h2>Not every booking is a good one</h2><p>It’s tempting to book anything that will say yes, especially with a number to hit. But a meeting with no real problem behind it, or with someone who can’t make the decision, usually ends in a polite “let me think about it.” It uses up an hour of the person running it, and it teaches your team to trust your bookings a little less. Five solid appointments beat ten shaky ones.</p><blockquote>Book meetings that can go somewhere, not meetings that fill a calendar.</blockquote><LessonFigure src="/lesson-qualified-appointment.png" alt="Split scene: a frustrated rep with a tray overflowing with failed bookings, next to a rep with four solid appointments, each backed by a real problem, the right people, a statement and clear timing" caption="A pile of shaky bookings versus a few solid ones. The solid ones are the ones that actually go somewhere." /><h2>The checklist</h2><p>Before you call it booked, check the short list from Module 5. <b>A reason in their words:</b> a real problem or goal, not just “open to a look.” <b>The right people:</b> whoever makes or shapes the decision will be there, or has agreed to be. <b>A statement:</b> they’ll have a recent processing statement ready, so the meeting can deal in real numbers. <b>Nothing blocking it:</b> you know about any contract, lease or timing issue that could stop a change, and the meeting still makes sense with it.</p><LessonFigure src="/lesson-qualified-appointment-2.png" alt="A rep checking off four items on a call: the problem, both decision-makers, the statement, and timing flagged for attention, all leading into a booked statement review" caption="A reason, the right people, a statement, and timing everyone knows about. Then it’s a qualified appointment." /><h2>Timing problems aren’t always deal-breakers</h2><p>A merchant with eight months left on a contract, or an early-termination fee, can still be worth meeting. They may want to know what they’re paying now and plan for the change. What matters is that both of you know about it going in. Surprising the person who runs the meeting with a two-year equipment lease is how good appointments turn into wasted ones.</p><h2>Be honest about what the meeting is</h2><p>Never book a meeting under a softer description than the real one. If it’s a sales conversation, don’t call it a “free audit with no strings” and then pitch. Merchants remember being misled, and they tell other owners. Describe it accurately, even if a few say no. The ones who say yes will actually show up ready to talk.</p></>},
 "make-it-stick":{kicker:"Lesson 3 of 4",title:"Make It Stick",lead:"A booked meeting isn’t a kept one. The last minute of the call, and the first few after it, decide whether the merchant actually shows up.",body:<><h2>Specific plans get kept</h2><p>Psychologist Peter Gollwitzer spent years studying what he called implementation intentions: plans that spell out when, where and how. People who make them follow through far more often than people who only intend to. In a 2011 study, Katherine Milkman and colleagues found that simply prompting employees to write down the date and time they’d get a flu shot raised vaccination rates, from about 33 percent to 37 percent, with no other change. A vague “sometime next week” gets forgotten. A specific plan the merchant says out loud gets kept.</p><blockquote>End the call with a plan they can repeat back to you.</blockquote><h2>Confirm it before you hang up</h2><p>Ask the merchant to put it in their calendar while you’re still on the phone: “Could you pop that in your calendar now, so it doesn’t get buried?” Then confirm the details together: the day and time, where it happens (at their business, by phone, or on video), who will be there, and that they’ll have the statement ready. If someone else needs to be in the room, ask how they’ll let that person know.</p><LessonFigure src="/lesson-make-it-stick.png" alt="A restaurant owner adding the meeting to his phone calendar while still on the call, as the rep confirms the day and time, the location, and who will attend" caption="Get it on their calendar before you hang up, and confirm when, where and who together." /><h2>Send the invite right away</h2><p>Send a calendar invite within a few minutes of hanging up, while the call is still fresh. Keep it short: the time, the place, who’s coming, one line on what you’ll cover in their words (“going through the fees that change every month”), and a reminder to bring a recent statement. A clear invite is also proof that you do what you say, which is a good first impression before the meeting even starts.</p><h2>Confirm the day before</h2><p>A short confirmation the day before cuts no-shows. Keep it easy to answer: “Looking forward to tomorrow at 2:30. Still a good time?” If the time no longer works, that’s good to know now. Offer two new options on the spot. A merchant who reschedules is still in; a merchant who quietly doesn’t show up usually isn’t.</p><LessonFigure src="/lesson-make-it-stick-2.png" alt="A rep sends a clear calendar invite, then a day-before text asking “Tomorrow 2:30?”, which leads to a confirmation, a reschedule to one of two new times, or silence" caption="Send the invite right away and confirm the day before. A confirmation or a reschedule both keep the meeting alive." /></>},
 "the-handoff":{kicker:"Lesson 4 of 4",title:"Hand It Off Well",lead:"If someone else runs the meeting, your job isn’t done when the call ends. What you pass along decides whether the merchant has to start over or feels like they were heard.",body:<><h2>Don’t make them repeat themselves</h2><p>Nothing tells a merchant they’re just a lead faster than being asked the same questions twice. If they told you the fees jump around every month and their partner handles the books, the person who walks in should already know that. A good handoff lets the meeting pick up where your call left off.</p><blockquote>The merchant should feel like the meeting is the second half of your call, not a new sales pitch.</blockquote><h2>What the handoff note needs</h2><p>Write it the same day, while you still remember the details. <b>The problem in their words,</b> quoted where you can. <b>Who’s coming,</b> and who decides. <b>The statement:</b> whether they’ll have one ready. <b>Timing:</b> contract end dates, leases, a new location, a POS change. <b>Loaded words</b> you heard, like a bad experience with a past processor. <b>Anything you promised,</b> such as “twenty minutes” or “we’ll tell you if you’re already in good shape.”</p><LessonFigure src="/lesson-the-handoff.png" alt="A rep handing a colleague an appointment brief with the merchant's quote, the fee pattern, both attendees, the statement, the date and a twenty-minute promise" caption="The handoff note carries the merchant’s words, who’s coming, the statement, timing, and every promise you made." /><h2>Promises travel with the appointment</h2><p>If you told the merchant the meeting would take twenty minutes, it has to take twenty minutes. If you said there’d be no pressure, there can’t be any. Whoever runs the meeting inherits every promise you made on the call, so make sure they know each one. Keeping them is how the merchant learns your team can be trusted.</p><h2>Close the loop</h2><p>After the meeting, find out what happened: whether it went ahead, what came of it, and whether your notes matched what the merchant said in person. It’s the fastest way to learn which of your appointments really are qualified. If the answer was “not a fit,” ask why, and use it to sharpen the checklist from Lesson 2 for your next call block.</p><LessonFigure src="/lesson-the-handoff-2.png" alt="The colleague walks the owner through his statement in the promised twenty minutes with no pressure, while the rep who booked it reviews the outcome against the handoff notes" caption="The meeting keeps the promises from the call, and the rep who booked it learns what happened." /></>},
 "yes-comes-later":{kicker:"Lesson 1 of 4",title:"Most Yeses Come Later",lead:"Plenty of merchants who say “not right now” mean exactly that. The rep who’s still around, and still welcome, when “now” arrives is the one who gets the appointment.",body:<><h2>Timing is usually the real reason</h2><p>A merchant might be in the middle of their busy season, locked into a contract for eight more months, or opening a second location next spring. None of that is a no to you. It’s a no to this week. If you give up after one call, the opportunity doesn’t disappear. It goes to whoever calls when the timing is right.</p><blockquote>Follow-up isn’t about wearing them down. It’s about being there when the timing changes.</blockquote><LessonFigure src="/lesson-yes-comes-later.png" alt="A restaurant owner waves off the call during a busy season with a contract and a new location ahead; the rep notes it, and months later the same owner is glad to hear from him" caption="“Not right now” usually means busy season, a contract or an expansion. Note the reason, and be there when it changes." /><h2>Familiar is comfortable</h2><p>In 1968, psychologist Robert Zajonc showed that people come to like things more simply by being exposed to them more often, whether that’s words, faces or symbols, even when they don’t remember seeing them. A name the merchant has seen a few times, attached to calls that were polite and useful, stops feeling like a stranger’s. That only works if each contact is a good one. Repeated annoyance breeds annoyance, not familiarity.</p><h2>Chasing versus following up</h2><p>Chasing sounds like “Just checking in to see if you’ve had a chance to think about it.” It asks the merchant for something and gives nothing back. Following up sounds like “You mentioned your contract ends in March, so I wanted to reach out before you’re locked in again.” It’s about their business, it’s based on what they told you, and it has a reason. The difference is whether the merchant is glad you called.</p><LessonFigure src="/lesson-yes-comes-later-2.png" alt="Split scene: an annoyed owner buried in repeated check-in messages and missed calls, next to the same owner smiling at one timely follow-up about his March contract end date" caption="Chasing piles on check-ins. Following up brings one message with a reason, based on what they told you." /><h2>Every follow-up starts on the first call</h2><p>The best follow-ups are planned before you hang up the first time. Ask when it would make sense to talk again, and why: “When would be a better time to revisit this?” Write down what they said and the reason they gave. That answer becomes the reason for your next call, and the merchant will remember that they asked for it.</p></>},
 "give-them-a-reason":{kicker:"Lesson 2 of 4",title:"Give Them a Reason to Hear From You",lead:"Every follow-up should give the merchant something: an answer, an idea, or a reminder they’ll actually want. If you can’t say what’s in it for them, don’t send it yet.",body:<><h2>Something useful makes a real difference</h2><p>In a 1971 study, Dennis Regan had participants rate paintings alongside a partner who was secretly working with him. During a break, the partner left and came back with two Cokes, one for the participant. Later, the partner asked the participant to buy raffle tickets. People who had been given the Coke bought about twice as many tickets as those who hadn’t, even though nobody had asked for the drink. A small, unrequested favor made people want to give something back.</p><blockquote>If you can’t say what’s in it for them, you’re not following up. You’re checking in.</blockquote><h2>What counts as value</h2><p>It doesn’t have to be big. <b>An answer:</b> something they asked about on the call that you’ve now looked into. <b>Something relevant to their business:</b> a change that affects their kind of merchant, such as new rules for surcharging or a common problem in their vertical, tied back to what they told you. <b>A timing reminder:</b> “Your contract ends in about sixty days. If you want a comparison before it renews, now’s the time.” Generic newsletters and “touching base” messages don’t count.</p><LessonFigure src="/lesson-give-them-a-reason.png" alt="A rep choosing between an answered question, something relevant to a restaurant, and a sixty-day contract reminder, while generic newsletters are set aside, and the owner replies with a thumbs up" caption="An answer, something relevant to their business, or a timing reminder. Generic newsletters don’t make the cut." /><h2>Use their words</h2><p>Open every follow-up with something the merchant actually said: “When we spoke in June, you mentioned the fees seemed to change every month.” It proves you listened, it reminds them of their own problem, and it makes the message impossible to mistake for a mass email. Your notes from Module 5’s discovery are the raw material here.</p><h2>Keep the ask small</h2><p>End each follow-up with one easy next step, not a big commitment: “Would it help if I looked at one statement?” or “Worth ten minutes before the renewal?” A small yes is easy to give, and it moves things forward. If they don’t want to take it, you haven’t burned anything.</p><LessonFigure src="/lesson-give-them-a-reason-2.png" alt="A rep opening a follow-up with what the owner said in June about fees jumping around, then asking for one statement and ten minutes, while the owner gives a thumbs up" caption="Open with their words from the last call, then ask for something small: one statement, ten minutes." /></>},
 "a-cadence-you-can-keep":{kicker:"Lesson 3 of 4",title:"Build a Cadence You Can Keep",lead:"Follow-up works when it’s planned and consistent, not when it depends on remembering. A simple system beats good intentions every time.",body:<><h2>Let the merchant set the clock</h2><p>The best timing is the timing the merchant gave you. If they said “after the holidays,” call the first week of January. If their contract ends in March, reach out in January so there’s time to compare. If they said “try me in a couple of weeks,” call in two weeks, not ten days and not a month. Following their timeline shows you listened, and it takes the guesswork out of when to call.</p><blockquote>Always leave a call knowing when the next one happens and why.</blockquote><h2>Mix the channels</h2><p>A phone call, a short email and a voicemail each reach the merchant differently. Owners who never answer at 2 p.m. may read email at 10 at night. A voicemail can point to an email: “I sent you a note about your contract renewal, just a couple of lines.” Use the channel that suits the message: quick questions by phone, anything they’ll want to reread by email.</p><h2>Space it sensibly</h2><p>When there’s no specific date, start closer together and spread out over time: a follow-up within a few days of a good call, then a week or two later, then monthly, then quarterly for merchants whose timing is a long way off. Calling every day is chasing. Disappearing for six months with no reason means starting from scratch.</p><LessonFigure src="/lesson-a-cadence-you-can-keep.png" alt="A chef names his timing: after the holidays, when the contract ends, in two weeks. Below, a row of daily calls is marked wrong, a long silence is marked no, and well-spaced follow-ups are marked right" caption="Let the merchant set the clock. Daily calls are chasing, and silence starts you over. Spacing that widens over time works." /><h2>Write it down every time</h2><p>After every contact, record three things in your CRM or tracker: what happened, what they said (in their words), and the next step with a date. Then set the reminder. A follow-up you’re trying to remember is one you’ll forget. It also means anyone on your team can pick up the relationship if they need to, the same way a good handoff works in Module 7.</p><LessonFigure src="/lesson-a-cadence-you-can-keep-2.png" alt="A rep moving from a call to an email to a voicemail pointing to the email, then logging what happened, the merchant's words, and the next step with a reminder, while the owner reads the email after dinner service" caption="Mix calls, emails and voicemail, then log what happened, their words, and the next step with a date." /></>},
 "close-the-file":{kicker:"Lesson 4 of 4",title:"Know When to Close the File",lead:"Good follow-up has an end. Knowing when to stop protects your reputation, respects the merchant, and frees your time for the people who do want to talk.",body:<><h2>Signs it’s time to stop</h2><p>Several well-spaced, useful follow-ups with no reply at all. A clear “we’re not interested, please don’t call again.” A business that turned out to be the wrong fit, like one that just signed a long contract with a steep cancellation fee and has no reason to revisit it. None of these call for one more try. They call for closing the file, at least for now.</p><blockquote>Stopping gracefully is part of following up well.</blockquote><h2>Honor every request to stop</h2><p>If a merchant asks you not to call again, don’t. Note it in your system right away so nobody else on your team calls either, and follow your company’s do-not-call policy and the rules that apply to your calls. There’s no clever way around a clear request, and trying one is the fastest way to turn a neutral merchant into one who warns other owners about you.</p><LessonFigure src="/lesson-close-the-file.png" alt="A rep closing three files: no reply after several follow-ups, a request to stop, and a locked-in long contract, while a do-not-call flag stops everyone on the team from calling that business" caption="No reply after several good tries, a request to stop, or no reason to revisit: close the file, and flag it for the whole team." /><h2>Send an honest last message</h2><p>When someone has gone quiet, a short, respectful closing note often gets the reply that nothing else did: “I haven’t heard back, so I’ll assume the timing isn’t right and stop reaching out. If anything changes, like your contract coming up for renewal, I’m happy to help.” It isn’t a trick. Mean it, and actually stop. It leaves the door open and ends things on good terms.</p><h2>Closed isn’t forever</h2><p>Some files deserve a note to check back much later: a contract that ends next year, a business planning to expand, an owner who liked you but couldn’t switch. Set a long-range reminder, and when the date comes, start fresh with a reason: “When we spoke last year, you mentioned your contract would be up about now.” A merchant who was treated well the first time is a warm call the second time.</p><LessonFigure src="/lesson-close-the-file-2.png" alt="A rep sends a courteous closing note and marks the file closed with a reminder for next year, when the contract is up; a year later the owner is happy to take his call" caption="A gracious last message, a closed file, and a reminder for next year. Treated well once, she’s a warm call the second time." /></>},
 "work-the-inputs":{kicker:"Lesson 1 of 4",title:"Work the Part You Control",lead:"You can’t control who answers, who’s in a contract, or who’s having a bad day. You can control how many calls you make and how well you make them. Judge your day by that.",body:<><h2>Two lists</h2><p>Some things on a call belong to you: how many dials you make, how prepared you are, whether your opener is about them, whether every follow-up goes out on the day you promised, and whether your notes get logged. Other things don’t: whether the owner picks up, whether they just signed a three-year contract, whether the lunch rush started early. Most frustration in this job comes from grading yourself on the second list.</p><blockquote>A good day is one where you did your part well, whatever the merchants did with theirs.</blockquote><LessonFigure src="/lesson-work-the-inputs.png" alt="A rep on a call between two lists: on the left, his part (dials, prepared notes, a merchant-specific opener, same-day follow-up, logging in the CRM); on the right, what isn't his (an unanswered phone, a three-year contract, a lunch rush, a stressed owner)" caption="Your part is the dials, the preparation, the opener, the follow-up and the notes. Who answers, and what kind of day they’re having, isn’t." /><h2>Why the second list wears you down</h2><p>If the only thing that counts is booked appointments, most days feel like losing, because most calls don’t end in one. Module 2 showed that dials and conversations predict results. The mindset half is just as important: when you judge the day by what you controlled, a day with no appointments can still be a good day, and you come back the next morning ready to dial instead of dreading it.</p><h2>Small wins keep you going</h2><p>Harvard researcher Teresa Amabile and Steven Kramer collected nearly 12,000 daily diary entries from 238 people working on projects across seven companies. Of everything that made a workday feel good, the most common was making progress on meaningful work, and small steps counted as much as big breakthroughs. On a call block, small wins are real: a gatekeeper who gave you the owner’s name, an opener that got a laugh, a merchant who agreed to find their statement. Notice them, and write the good ones down.</p><h2>Set input goals</h2><p>Write the day’s goals in terms you control: “Finish both call blocks. Every follow-up due today goes out. Every call logged before lunch.” You’ll hit those most days, and the appointments follow from them over time. If you want a stretch goal, make it about quality: “Ask one real impact question on every conversation.”</p><LessonFigure src="/lesson-work-the-inputs-2.png" alt="A rep smiling as he writes “1 impact question” in his notebook, with every input goal checked off on his screen and zero appointments, while small wins float by: the owner's name, a merchant saying “That's a great point,” and an offer to pull a statement" caption="Zero appointments today, and still a good day: every input goal done, and a string of small wins on the way." /></>},
 "keep-honest-score":{kicker:"Lesson 2 of 4",title:"Keep Honest Score",lead:"Your numbers only help if they’re true. A scorecard you round up in your head will tell you everything is fine right up until it isn’t.",body:<><h2>Watching your progress works</h2><p>In 2016, Benjamin Harkin and colleagues combined the results of 138 experiments with nearly 20,000 people. Across goals as different as exercise, diet and studying, people who were prompted to monitor their progress were more likely to reach their goals. The effect was stronger when progress was physically written down or shared with someone else. Keeping score isn’t paperwork. It’s part of how the goal gets reached.</p><blockquote>Count the same way every day, and write it down while it’s still true.</blockquote><h2>Know your ratios</h2><p>Four numbers tell most of the story: dials, conversations with a decision-maker, appointments booked, and appointments that actually happen. Divide each one by the one before it. After a few weeks you’ll know your own ratios, something like one conversation for every eight dials and one appointment for every six conversations. Those ratios turn a vague goal into a plan: if you want four appointments a week, you know roughly how many conversations, and how many dials, that takes.</p><LessonFigure src="/lesson-keep-honest-score.png" alt="A rep logging calls as a funnel of dials, decision-maker conversations, appointments booked and appointments held floats beside him, with voicemails and “call next week” counted separately instead of as conversations" caption="Dials, conversations, booked, held. Voicemails and “call me next week” get their own count, not a place in the funnel." /><h2>The ratio shows you the leak</h2><p>When results drop, the ratios tell you where to look. Plenty of dials but few conversations points to the list or the time of day. Plenty of conversations but few appointments points to the opener, discovery, or how you ask for the meeting (Modules 3, 5 and 7). Appointments that don’t happen point to how you make them stick. Fixing the right step is much faster than just working harder at all of them.</p><LessonFigure src="/lesson-keep-honest-score-2.png" alt="A manager pointing at a funnel dashboard where the conversations step is flagged in amber, while the rep beside her studies it; a flattering A-minus scorecard sits next to an honest C-plus one" caption="An honest scorecard points at the step that’s leaking, so the fix goes where it’s needed." /><h2>Don’t round up</h2><p>A voicemail isn’t a conversation. “Call me next week” isn’t an appointment. Counting them as if they were feels better for a day, and then your ratios stop meaning anything and you can’t find the real problem. Use the same definitions every day, log calls as you make them, and look at the numbers once a week. An honest bad week is useful. A flattering one isn’t.</p></>},
 "habits-that-hold":{kicker:"Lesson 3 of 4",title:"Build Habits That Hold",lead:"Motivation comes and goes. A habit shows up on the days you don’t feel like it. The goal is to make dialing something you do, not something you decide to do.",body:<><h2>How long a habit really takes</h2><p>You may have heard that a habit takes 21 days. The research says otherwise. In a 2010 study, Phillippa Lally and colleagues at University College London asked 96 volunteers to repeat a new daily behavior, like a walk after breakfast or a glass of water with lunch, and tracked how automatic it felt. On average it took 66 days for the behavior to level off as automatic, and the range ran from 18 days to 254. Expect about two months of steady effort, not three weeks.</p><blockquote>Missing one day doesn’t break a habit. Missing it twice starts a new one.</blockquote><LessonFigure src="/lesson-habits-that-hold.png" alt="A row of the same rep at his desk over time, from hesitant on day 1 to relaxed by day 66, along a rising line; a crossed-out “21” sits at the start, a missed day 45 barely dents the line, and the range runs from 18 to 254 days" caption="Not 21 days. About 66 on average, anywhere from 18 to 254, and one missed day doesn’t knock it off course." /><h2>Same time, same place, same first step</h2><p>Habits form around cues. Tie your first dial to something that already happens every day: coffee on the desk, list open, first number dialed by 9:05. That’s the call block from Module 2 and the pre-call routine that goes with it. The more often the same cue leads to the same action, the less you have to talk yourself into it.</p><h2>Make the start small</h2><p>The hardest part of a call block is the first dial. Don’t make the habit “have a great call block.” Make it “dial the first number before opening email.” That’s small enough to do on your worst morning, and once the first call is done, the second one is much easier. Build the habit around starting, and the rest of the block tends to follow.</p><h2>A missed day isn’t a failure</h2><p>Lally’s volunteers who missed a single day didn’t lose their progress. The habit kept building as long as they picked it back up. So when a sick day, a training session or a long meeting knocks out a call block, don’t write off the week. Get the next block in. The danger isn’t missing once. It’s letting one missed day turn into “I’ll start fresh Monday.”</p><LessonFigure src="/lesson-habits-that-hold-2.png" alt="A rep dialing his first call at 9:05 with coffee on the desk, the next calls following one after another; below, a missed day followed by a call block back on track, next to two missed days in a row that end with the rep slumped at his desk" caption="First dial by 9:05, and the rest of the block follows. One missed day, then back at it, is fine. Two in a row is how the habit slips." /></>},
 "bounce-back":{kicker:"Lesson 4 of 4",title:"Bounce Back From a Bad Week",lead:"Every rep has bad weeks. What separates the reps who last is the story they tell themselves about why it happened.",body:<><h2>How you explain a bad week matters</h2><p>In a 1986 study, psychologist Martin Seligman and Peter Schulman looked at life insurance agents, a job with plenty of rejection. Agents with a more optimistic way of explaining setbacks sold about 37 percent more insurance than agents with a more pessimistic style over their first two years. And among new hires, the pessimists were about twice as likely to quit in their first year. Talent and training mattered, but so did how agents made sense of a string of no’s.</p><blockquote>Explain a bad week in a way you can do something about.</blockquote><h2>Three questions to ask yourself</h2><p>Seligman described explanations along three lines. <b>Is it permanent?</b> “I’m just not good at this” is permanent. “This week’s list was thin” isn’t. <b>Is it everywhere?</b> “Nothing I do works” covers everything. “My opener ran long this week” covers one thing. <b>Is it all about me?</b> “I’m not a salesperson” puts all of it on who you are. Usually some of it is the list, the season or plain timing, and the part that’s yours is something you did, like “I didn’t ask for the meeting on three good calls.” What you did can change.</p><h2>Rewrite the story, honestly</h2><p>This isn’t pretending a bad week was fine, and it isn’t blaming the list for everything. It’s finding the explanation that’s both true and fixable. Look at your numbers from Lesson 2. If your dials were down, that’s the fix. If your dials were fine but conversations didn’t turn into appointments, pick the one step to work on. “Next week I’ll ask for the meeting on every good call” is a plan. “I’m bad at this” isn’t.</p><LessonFigure src="/lesson-bounce-back.png" alt="Split scene: a slumped rep under clouds marked with an infinity sign, a globe and a crossed-out figure (permanent, everywhere, all about me), and the same rep calmly writing a plan built from his numbers, one step, and a booked meeting" caption="From “it’s permanent, it’s everything, it’s me” to one true, fixable step, backed by the numbers." /><h2>A reset routine</h2><p>At the end of a rough week, do three things. Look at what you controlled: did you do your part? Pick one thing to change next week, not five. Then put Monday’s first call block on the calendar before you leave. If the bad weeks keep stacking up, talk to your manager. They can see your numbers, and a second pair of eyes usually finds the leak faster than you can alone.</p><LessonFigure src="/lesson-bounce-back-2.png" alt="A manager and rep reviewing the week together: first what the rep controlled, then one goal picked for next week, then Monday's first call block placed on the calendar at 9 a.m." caption="Review what you controlled, pick one thing to change, and put Monday’s first call block on the calendar." /></>},
 "whos-answering":{kicker:"Lesson 1 of 4",title:"Who’s Really Answering the Phone",lead:"At most small businesses, the person who picks up isn’t the owner. How you treat that person decides whether you ever reach the one who decides.",body:<><h2>Gatekeepers come in many forms</h2><p>In merchant services, the gatekeeper is rarely a receptionist behind a big desk. It’s the host at a restaurant, the cashier at a boutique, the service writer at an auto shop, the office manager at a dental practice, or the owner’s spouse who handles the books. Each one is doing a real job, and screening sales calls is part of it. Owners get several a week, and the person on the phone has been asked to protect their time.</p><blockquote>The gatekeeper isn’t an obstacle between you and the owner. They’re the first person you need to earn.</blockquote><h2>They have more influence than you think</h2><p>The person who answers often knows things the owner doesn’t say on a cold call: which processor they use, whether the terminal keeps dropping, when the contract comes up, who really makes the decision, and the best time to call. Many also have the owner’s ear. “Some guy called about the card machine” and “A really nice rep called, and I think it’s worth five minutes” are very different messages to pass along.</p><LessonFigure src="/lesson-whos-answering.png" alt="A rep on the phone while gatekeepers at a restaurant, a boutique, an auto shop and a dental office take calls; one tells her owner “He’s a great fit. You should take the call,” while another passes along “Just another sales call” to an unimpressed owner" caption="The host, the cashier, the service writer, the office manager. What they tell the owner about your call matters more than you’d think." /><h2>Learn their name and use it</h2><p>Ask for the gatekeeper’s name early, and write it down: “Before I go, who am I speaking with?” People notice their own name. In a 2006 brain-imaging study, Dana Carmody and Michael Lewis found that hearing your own name activates different, more self-focused areas of the brain than hearing someone else’s. Using it the next time you call (“Hi Jenna, it’s Alex again”) tells them you see them as a person, not a hurdle.</p><h2>Match the moment</h2><p>A host during the dinner rush or a cashier with a line at the register has seconds, not minutes. If it’s clearly a bad time, say so before they have to: “Sounds like you’re slammed. When’s a quieter time to call back?” Reading the room is the fastest way to be remembered as the rep who was easy to deal with.</p><LessonFigure src="/lesson-whos-answering-2.png" alt="A rep asks a busy host “Who am I speaking with?” and offers to call back at a quieter time, saving her name, Jenna, and a 3:00 callback in his notes; on the next call he greets her with “Hi Jenna, it's Alex again” and she smiles" caption="Ask their name, notice when it’s a bad time, and use their name when you call back." /></>},
 "be-straight":{kicker:"Lesson 2 of 4",title:"Be Straight About Who You Are",lead:"The old tricks for getting past a gatekeeper all involve some kind of pretending. They work once, at best, and they cost you the account.",body:<><h2>The tricks, and why they fail</h2><p>Some reps are taught to get past the front desk with a little deception: “It’s personal,” “He’s expecting my call,” “I’m returning his call,” or pretending to be a customer with a problem. Gatekeepers have heard all of them. Even when one works, the owner picks up already knowing they were tricked. You’ve reached the decision-maker and lost them in the same moment.</p><blockquote>Never say anything to a gatekeeper you wouldn’t want repeated to the owner word for word.</blockquote><LessonFigure src="/lesson-be-straight.png" alt="Split scene: a rep holding a mask with thought bubbles of a fake identity and a pretend callback, leading to a suspicious owner and broken trust; next to the same rep giving his name, company and reason plainly, and a smiling host passing him to a friendly owner" caption="Tricks get you to the owner with trust already broken. A plain, honest introduction gets you passed along." /><h2>Broken trust doesn’t fully come back</h2><p>In a 2006 study, Maurice Schweitzer, John Hershey and Eric Bradlow tracked how trust recovered after people were let down in a series of trust games. When the other player had simply been unreliable, trust could be rebuilt with consistent good behavior. When the player had lied, trust never fully recovered, even after apologies and a long run of honest play. Small businesses talk to each other, and a rep who tricked the front desk is a story that gets told.</p><h2>Say who you are and why you’re calling</h2><p>Give your name, your company, and a short, honest reason, the same way you would with the owner: “Hi, this is Alex with BytePOS. I help restaurants around here figure out what they’re really paying to take cards. Who usually handles that for you?” It’s clear and it’s respectful, and it’s about their business. Many gatekeepers will tell you exactly who to talk to, because you asked plainly.</p><h2>“What’s this regarding?” is a fair question</h2><p>Answer it directly. Vague answers like “just a business matter” sound like you’re hiding something, because you are. A specific, honest answer gives the gatekeeper something to pass along, and lets them decide it’s worth passing on. If they say the owner isn’t interested, thank them and ask whether it’s all right to check back in a few months. Pushing past a clear no from the front desk works about as well as it does with the owner.</p><LessonFigure src="/lesson-be-straight-2.png" alt="A host asks “What's this regarding?”; the rep skips a vague “Business matter” and explains he helps restaurants review their card processing statements, and she writes it down to pass to the owner; in a second path she says the owner isn't interested and he notes to check back in six months and thanks her" caption="A specific, honest answer gives the gatekeeper something to pass along. If it’s a no, thank them and note when to check back." /></>},
 "ask-for-help":{kicker:"Lesson 3 of 4",title:"Ask for Help, Not Access",lead:"“Can I speak to the owner?” asks the gatekeeper to let you in. “Could you help me figure out who handles this?” asks them to help, and most people like to help.",body:<><h2>People say yes more often than we think</h2><p>In a 2008 study, Francis Flynn and Vanessa Lake had participants ask strangers for small favors, like filling out a short questionnaire. Beforehand, the participants guessed how many people they’d need to ask. They overestimated by about double: people said yes far more often than expected. The same fear that makes cold calls hard makes reps assume gatekeepers will block them, and they often won’t.</p><blockquote>Asking for help turns the gatekeeper from a guard into a guide.</blockquote><h2>Change the question</h2><p>“Is the owner available?” has two easy answers: yes or no, and no is safer. A request for help invites a real answer. <b>Who:</b> “Who usually looks at the card processing, the owner or someone else?” <b>When:</b> “When’s the best time to catch her for two minutes?” <b>How:</b> “Would it be better to email her first, or just call back?” Each question is easy to answer, and each answer moves you closer.</p><LessonFigure src="/lesson-ask-for-help.png" alt="Split scene: a rep asking to speak to the owner gets a yes-or-no choice with no winning, while the same rep asking for help gets a smiling host offering who, when and how" caption="“Is the owner available?” invites a no. Asking who, when and how invites help." /><h2>Ask what they know</h2><p>Gatekeepers are often the ones who deal with the card machine every day. A light question can open a real conversation: “Does the terminal ever give you trouble at the busy times?” If they say it drops every Friday night, you now have a reason about them for your call to the owner, straight from Module 3, and you can mention where it came from: “Jenna mentioned the terminal drops on busy nights.”</p><h2>Take the path they give you</h2><p>If the gatekeeper says to call Tuesday after two, call Tuesday after two, and say so: “Jenna said this would be a good time.” If they suggest an email, send a short one and mention them. Following their advice shows you listened, and it makes them part of the process. A gatekeeper whose advice you took is far more likely to help again.</p><LessonFigure src="/lesson-ask-for-help-2.png" alt="A rep takes notes as Jenna, the host, mentions the terminal drops during the Friday rush and suggests calling Tuesday after two or emailing first; his notebook turns her words into a reason for the owner, and he calls back Tuesday after two as she suggested" caption="Jenna’s words become the reason for the owner call, and calling Tuesday after two, as she suggested, makes her part of it." /></>},
 "make-an-ally":{kicker:"Lesson 4 of 4",title:"Turn Gatekeepers Into Allies",lead:"You’ll call the same businesses again and again. A gatekeeper who likes dealing with you is worth more than any opener.",body:<><h2>Thanks makes people help again</h2><p>In a 2010 study, Adam Grant and Francesca Gino had participants give feedback on a student’s cover letter, then asked them for help with a second one. Participants who had received a short note of thanks for the first round were more than twice as likely to help again, 66 percent compared with 32 percent. Feeling appreciated made them feel their help mattered. Thanking a gatekeeper sincerely, by name, for a small bit of help is how the next call gets easier.</p><blockquote>Treat the front desk the way you’d treat the owner, because the owner will hear about how you did.</blockquote><h2>Remember them</h2><p>Put the gatekeeper in your CRM like any other contact: their name, their role, what they told you, and the best time to call. The next time you call, pick up where you left off: “Hi Jenna, it’s Alex. You mentioned Maria’s easier to catch on Tuesdays, so here I am.” Being remembered is rare in a week full of sales calls, and people notice it.</p><LessonFigure src="/lesson-make-an-ally.png" alt="A rep thanks Jenna, saves her as the host in his CRM with the owner's schedule pattern and Tuesday, calls back on Tuesday greeting her by name, and she gives a thumbs up and passes the call through to the owner" caption="Thank them, remember them, and call when they said to. The next time, they’re the one putting you through." /><h2>Keep your promises to them, too</h2><p>If you said you’d only need two minutes of the owner’s time, take two minutes. If you said you’d email first, email first. Everything from Module 7 about promises applies here: the gatekeeper put a little of their credibility behind you. Keep your word and they’ll do it again. Break it and you won’t get another chance.</p><h2>When the answer is no</h2><p>Sometimes the gatekeeper has been told to turn away every sales call, and no amount of courtesy will change that. Respect it. Thank them, note it in your CRM, and try a different route if there is one, such as stopping by in person during a quiet hour or a short letter to the owner, or come back months later with a real reason. A gatekeeper who remembers you as polite on the way out may be the one who says “actually, she’s free now” next time.</p><LessonFigure src="/lesson-make-an-ally-2.png" alt="Split scene: a rep keeps his promises to an office manager (email sent first, under two minutes, her credibility respected); next to a gatekeeper saying “We don't take sales calls,” which he records in the CRM with later options of an in-person visit, a short letter, or a check-back in six months with a real reason" caption="Keep every promise you made to get through. When the answer is no sales calls, respect it, note it, and pick a different route later." /></>},
 "not-interested":{kicker:"Lesson 1 of 4",title:"When They Say “Not Interested”",lead:"Ten seconds into a call, the merchant hasn’t heard enough to decide anything. “Not interested” is usually a reflex that protects their time, not a verdict on what you offer.",body:<><h2>A reflex, not a decision</h2><p>Owners get sales calls every week, and “not interested” is the fastest way to end any of them. It comes out before they know who you are or why you called. That makes it information about timing and relevance, not a judgment of you or your offer. It’s the same idea as Module 1: a merchant brushing off a call is responding to their circumstances, not grading you.</p><blockquote>Your job isn’t to overcome the objection. It’s to earn one more honest answer.</blockquote><h2>Steady yourself first</h2><p>Hearing “no” quickly sets off a small jolt of stress, and stressed reps either rush or argue. In a 2007 study in <i>Psychological Science</i>, Matthew Lieberman and colleagues at UCLA found that when people put a feeling into words, activity in the amygdala, the brain’s alarm system, dropped. You can use that on the phone. Name it to yourself (“that’s a reflex, not a no”), take one beat of silence, then answer. The pause also tells the merchant you aren’t about to steamroll them.</p><LessonFigure src="/lesson-not-interested.png" alt="A restaurant owner holding up a hand and saying no mid-rush, while the rep feels the jolt, pauses, and settles before answering" caption="The “no” lands as a jolt. Name it, take one beat, and answer from calm instead of reflex." /><h2>Acknowledge, then one easy question</h2><p>Don’t argue with the objection and don’t pretend you didn’t hear it. Agree with what’s true, give your reason in one line, and ask one question that’s easy to answer: “That’s fair, you weren’t expecting my call. Before I let you go, when did someone last walk you through your processing statement?” The question is low-stakes, it’s about their business, and any answer tells you something. If they give you a real answer, you’re back in discovery from Module 5.</p><h2>Know when to let go</h2><p>If the second answer is still no, take it. Thank them, ask whether it’s all right to check back in a few months, and end the call warmly. Pushing past two clear no’s rarely turns into an appointment, and it guarantees a cold reception the next time you call. A polite exit keeps the door open. Module 8 covers how to follow up without chasing.</p><LessonFigure src="/lesson-not-interested-2.png" alt="Four panels: the merchant says no, the rep acknowledges it and asks one question about the statement, then either the merchant opens up or the rep thanks them and notes a date to check back" caption="Acknowledge, ask one easy question, then follow their lead: back into discovery, or a warm exit and a date to check back." /></>},
 "were-happy":{kicker:"Lesson 2 of 4",title:"“We’re Happy With Who We Have”",lead:"“Happy” usually means “not unhappy enough to deal with switching.” That’s a reasonable position, and you’ll get further by treating it as one.",body:<><h2>Why switching feels expensive</h2><p>In their 1979 work on prospect theory, Daniel Kahneman and Amos Tversky showed that losses loom larger than gains of the same size. Switching processors comes with losses the owner can picture right away: paperwork, new equipment, retraining staff, the risk that something breaks on a busy day. The savings are a maybe. Add the status quo bias from Module 4, and “we’re happy” is a completely rational answer, not stubbornness.</p><blockquote>You’re not asking them to switch. You’re asking for a second look.</blockquote><LessonFigure src="/lesson-were-happy.png" alt="A contented café owner on the phone, with thought bubbles showing paperwork, staff retraining, new equipment and a busy rush, while the rep listens and nods" caption="To the owner, switching means paperwork, new equipment, retraining and risk on a busy day. “We’re happy” is a reasonable answer." /><h2>Don’t attack their processor</h2><p>Criticizing the merchant’s current provider means criticizing their decision, and people defend their decisions. Take them at their word: “Good, that’s what you want from a processor.” Now you’re not an opponent, and the next question lands differently.</p><h2>Ask what “happy” covers</h2><p>Happy with the service isn’t the same as knowing the cost. Ask a question that separates the two: “If you could change one thing about how payments work for you, what would it be?” or “When did someone last compare your statement against what’s out there?” Pricing on a merchant account can change over its life, sometimes announced in a line on the statement that few owners read. You don’t need to claim that happened to them. You only need to ask whether anyone has checked.</p><h2>Offer a check-up, not a switch</h2><p>A small request is easier to agree to than a big one, and it makes the next step easier too. In a classic 1966 study, Jonathan Freedman and Scott Fraser found that homeowners who first agreed to a small request were far more likely to agree to a much bigger one later. Asking to review a statement is small: “No change needed. Let me look at your last statement, and if you’re getting a fair deal, I’ll tell you so.” Then keep that promise. Telling a merchant they’re in good shape is how you become the rep they call when something changes.</p><LessonFigure src="/lesson-were-happy-2.png" alt="A rep reviewing a statement under a magnifying glass, then telling one merchant she's in good shape and booking a follow-up with another whose costs look high" caption="A check-up, not a switch. If they’re getting a fair deal, say so. If they aren’t, you’ve earned the next conversation." /></>},
 "send-me-information":{kicker:"Lesson 3 of 4",title:"“Just Send Me Some Information”",lead:"“Send me something” is often the politest way to end a call. Sometimes it’s real interest. One question tells you which.",body:<><h2>What it usually means</h2><p>Asking for information lets the merchant end the call without saying no. If you agree and hang up, you send a generic brochure, it lands in an inbox with dozens of others, and neither of you thinks about it again. It feels like progress, which is exactly why it’s easy to settle for.</p><blockquote>If they want information, find out which information. If they won’t say, they wanted off the call.</blockquote><h2>Agree, then narrow it</h2><p>Don’t push back on the request. Say yes, then ask what would make it worth reading: “Happy to. So I send something useful instead of a brochure, what matters most to you right now: what you’re paying, how fast you get funded, or how it works with your POS?” A merchant who’s genuinely interested will tell you, and their answer is discovery. One who wanted off the phone will stall, and that tells you where you stand.</p><LessonFigure src="/lesson-send-me-information.png" alt="A merchant asks for information; in one outcome he picks cost from three options the rep offers, in the other he waves it off and a brochure disappears into a crowded inbox" caption="Ask which information matters. A real answer is discovery. A shrug means the brochure was only ever going to get buried." /><h2>Tie it to a next step</h2><p>Information on its own doesn’t move anything forward. Attach a short, specific follow-up to it: “I’ll send it this afternoon. Can we take ten minutes Thursday morning to go over it together?” If they agree, you have an appointment in all but name. If they won’t commit to any next step at all, you’ve learned that without spending a week waiting on an email.</p><h2>Send what you promised</h2><p>When they do agree, send it the same day. Keep it short, make it about what they told you, and use their words: “You mentioned the fees change every month. Here’s how we’d show you exactly why.” A fast, specific follow-up is proof that you listened, and it sets up the next call.</p><LessonFigure src="/lesson-send-me-information-2.png" alt="A rep skips the generic brochure and sends a short email built around what the merchant said about his costs, then books a ten-minute Thursday call" caption="Skip the brochure. Send something short, built on their words, the same day, with the next step already on the calendar." /></>},
 "price-resistance":{kicker:"Lesson 4 of 4",title:"“What’s Your Rate?” and Price Pushback",lead:"Price comes up early on almost every merchant call. Quoting a number on the phone feels helpful, and it’s nearly always a mistake.",body:<><h2>Why a quoted rate misleads</h2><p>What a merchant actually pays depends on their card mix (debit, rewards and business cards cost different amounts), how cards are taken (tapped, keyed in, or online), and the pricing model on their account. A low headline rate can come with higher fees somewhere else. The honest comparison is the effective rate: total fees divided by total card volume, taken from a real statement. Anything else is a guess.</p><blockquote>Don’t compete on a number you haven’t earned the right to quote.</blockquote><LessonFigure src="/lesson-price-resistance.png" alt="A merchant weighed down by a heavy percent sign, surrounded by unknowns like card types and how cards are taken, while the rep lays them out on a statement to arrive at one effective rate" caption="A headline rate hides the card mix, how cards are taken and the extra fees. Total fees divided by total volume is the honest number." /><h2>The first number sticks</h2><p>In a 1974 study, Amos Tversky and Daniel Kahneman had people spin a wheel rigged to land on 10 or 65, then estimate the percentage of African countries in the United Nations. People who saw 10 guessed a median of 25 percent. People who saw 65 guessed 45. A number they knew was random still pulled their answer. A rate you quote on the phone works the same way: it becomes the anchor the merchant measures everything against, including the next rep’s teaser rate.</p><h2>What to say instead</h2><p>Be straight with them: “Honestly, anyone who quotes you a rate without seeing your statement is guessing. What I can do is work out what you’re really paying now, then show you what it would be with us.” Then ask what they pay today. Most owners don’t know their effective rate, and saying so out loud makes the statement review an easy yes.</p><h2>When they say you’re too expensive</h2><p>Ask what they’re comparing against: “Too expensive compared to what?” Often it’s a rate someone quoted them or a flat rate from a card reader they bought at a store. Compare total cost, not headline rates, and don’t offer a discount on the phone to save the call. If you honestly aren’t cheaper, say so. Then talk about what you do better only if it’s real and matters to them, like next-day funding, local support or a POS integration. A rep who admits when they’re not the lowest price is a rep merchants believe about everything else.</p><LessonFigure src="/lesson-price-resistance-2.png" alt="A skeptical merchant holds up a low-rate card while the rep weighs the headline rate against total cost, then points to next-day funding, local support and a confirmed POS integration" caption="Weigh total cost, not the headline rate. Then point to what you do better, but only if it’s real and matters to them." /></>},
};
export default async function LessonPage({params}:{params:Promise<{slug:string;lesson:string}>}){const {slug,lesson}=await params;const module=modules.find(m=>m.slug===slug);if(!module)notFound();const data=content[lesson];if(!data)notFound();return <AppShell active="Training"><PreviewGate status={module.status}><div style={{padding:"35px 4vw 70px",maxWidth:1120,margin:"auto"}}><ModuleBreadcrumb moduleSlug={slug} itemId={lesson}/><div style={{display:"grid",gridTemplateColumns:"1fr 280px",gap:22}}><article className="card" style={{padding:"clamp(28px,5vw,60px)"}}><div className="eyebrow">{data.kicker}</div><ReadAloud targetId="lesson-audio-text" /><div id="lesson-audio-text"><h1 className="display" style={{fontSize:42,margin:"18px 0 20px"}}>{data.title}</h1><p style={{fontFamily:"Georgia,serif",fontSize:22,lineHeight:1.5,color:"var(--green)",marginBottom:28}}>{data.lead}</p><div className="lesson-copy">{data.body}</div></div><div style={{borderTop:"1px solid var(--line)",marginTop:45}}><ModulePager moduleSlug={slug} itemId={lesson}><MarkComplete moduleSlug={slug} itemId={lesson} minutes={module.lessons.find(l=>l.id===lesson)?.minutes??2}/></ModulePager></div></article><aside><div style={{position:"sticky",top:95}}><div className="card" style={{padding:22}}><div className="eyebrow">In this module</div><div style={{marginTop:15}}>{module.lessons.map((l,i)=><Link key={l.id} href={lessonHref(slug,l)} style={{display:"flex",gap:10,padding:"11px 0",borderTop:"1px solid var(--line)",fontSize:12,fontWeight:l.id===lesson?900:600,color:l.id===lesson?"var(--green)":"var(--muted)"}}><span>{i+1}.</span>{l.title}</Link>)}</div>{data.image&&<Image src={data.image} alt="" width={1672} height={941} style={{width:"100%",height:"auto",borderRadius:12,marginTop:18,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}} />}</div>{data.image2&&<Image src={data.image2} alt="" width={1672} height={941} style={{width:"100%",height:"auto",borderRadius:12,marginTop:18,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}} />}{data.image3&&<Image src={data.image3} alt="" width={1672} height={941} style={{width:"100%",height:"auto",borderRadius:12,marginTop:18,boxShadow:"0 10px 30px rgba(10,11,10,.15)"}} />}</div></aside></div><style>{`.lesson-copy h2{font-family:Georgia,serif;font-size:29px;margin:35px 0 12px}.lesson-copy p{color:var(--muted);line-height:1.75;font-size:16px;margin:0 0 16px}.lesson-copy p:last-child{margin-bottom:0}.lesson-copy .lesson-figure{margin:26px 0 34px}.lesson-copy figcaption{margin-top:10px;font-size:13px;color:var(--muted);text-align:center}.lesson-copy blockquote{margin:30px 0;padding:24px 28px;border-left:5px solid var(--lime);background:#f2f6e7;font-family:Georgia,serif;font-size:21px;line-height:1.5}`}</style></div></PreviewGate></AppShell>}
